use vesta_bindings::{decoder::{decode_resource,DecodeBudget},resource_roles::{ResourceRole2,ResourcePayload2},profile_digests::PROFILE_DIGESTS};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn role(s:&str)->ResourceRole2{match s{"OpenBundle"=>ResourceRole2::OpenBundle,"InspectionPage"=>ResourceRole2::InspectionPage,"HostAck"=>ResourceRole2::HostAck,"HostNack"=>ResourceRole2::HostNack,"CommandCompletion"=>ResourceRole2::CommandCompletion,"FailureNotice"=>ResourceRole2::FailureNotice,_=>panic!("unknown fixture")}}
fn value(v:ResourcePayload2)->Value{match v{ResourcePayload2::OpenBundle(v)=>serde_json::to_value(v),ResourcePayload2::InspectionPage(v)=>serde_json::to_value(v),ResourcePayload2::HostAck(v)=>serde_json::to_value(v),ResourcePayload2::HostNack(v)=>serde_json::to_value(v),ResourcePayload2::CommandCompletion(v)=>serde_json::to_value(v),ResourcePayload2::FailureNotice(v)=>serde_json::to_value(v)}.unwrap()}
#[test]fn generated_typed_bytes_and_rejections(){let fixtures:Vec<Value>=serde_json::from_str(include_str!("../../../../tests/fixtures/resources.json")).unwrap();for f in fixtures{let r=role(f["role"].as_str().unwrap());let b=f["utf8"].as_str().unwrap().as_bytes();let d=&f["descriptor"];assert_eq!(value(decode_resource(r,d,b,DecodeBudget::default()).unwrap()),f["payload"]);let mut bad=d.clone();bad["byteLength"]=json!("0");assert!(decode_resource(r,&bad,b,DecodeBudget::default()).is_err());bad=d.clone();bad["sha256"]=json!("0".repeat(64));assert!(decode_resource(r,&bad,b,DecodeBudget::default()).is_err());bad=d.clone();bad["mediaType"]=json!("application/json");assert!(decode_resource(r,&bad,b,DecodeBudget::default()).is_err());assert!(decode_resource(r,d,b,DecodeBudget{max_bytes:1,..DecodeBudget::default()}).is_err());assert!(decode_resource(r,d,b,DecodeBudget{max_depth:0,..DecodeBudget::default()}).is_err());let mut payload=f["payload"].clone();payload["extra"]=json!(true);let first=payload.as_object().unwrap().keys().next().unwrap().clone();let mut wrong=f["payload"].clone();wrong[&first]=json!([]);for badbytes in [serde_json::to_vec(&payload).unwrap(),serde_json::to_vec(&wrong).unwrap(),vec![0xc3,0x28],b"{\"a\":0,\"a\":1}".to_vec(),b"\"\\ud800\"".to_vec()]{let mut desc=d.clone();desc["byteLength"]=json!(badbytes.len().to_string());desc["sha256"]=json!(format!("{:x}",Sha256::digest(&badbytes)));assert!(decode_resource(r,&desc,&badbytes,DecodeBudget::default()).is_err());}}}
#[test]fn profiles_match_full_independent_vector_table(){let v:Value=serde_json::from_str(include_str!("../../../../contracts/generated/profile-input-manifest.json")).unwrap();assert_eq!(PROFILE_DIGESTS.len(),9);for(k,h)in PROFILE_DIGESTS{assert_eq!(v["profiles"][k],*h);}}
